        "hasStockPreview": true,
        "css": {
          "source": "src/styles/primeng/_overrides.scss",
          "css": "// Severity uses the semantic scale: tier 2 is the tint, tier 3 the text on it,\n// tier 1 the accent. Dark mode swaps 2 and 3 in Figma, so this inverts for free.\nbody:not(.primeng-default) .ui-toast .ui-toast-message,\nbody:not(.primeng-default) .ui-messages,\nbody:not(.primeng-default) .ui-message {\n  border: 1px solid transparent;\n  border-radius: var(--curinos-dimensions-radii-semantic-cards);\n  box-shadow: none;\n  font-family: var(--curinos-typography-families-body);\n  font-size: var(--curinos-typography-font-size-sm);\n  font-weight: var(--curinos-typography-font-weight-medium);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-message-success,\nbody:not(.primeng-default) .ui-messages.ui-messages-success,\nbody:not(.primeng-default) .ui-message.ui-message-success {\n  background: var(--curinos-color-semantic-success-2);\n  border-color: var(--curinos-color-semantic-success-1);\n  color: var(--curinos-color-semantic-success-3);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-message-info,\nbody:not(.primeng-default) .ui-messages.ui-messages-info,\nbody:not(.primeng-default) .ui-message.ui-message-info {\n  background: var(--curinos-color-semantic-info-2);\n  border-color: var(--curinos-color-semantic-info-1);\n  color: var(--curinos-color-semantic-info-3);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-message-warn,\nbody:not(.primeng-default) .ui-messages.ui-messages-warn,\nbody:not(.primeng-default) .ui-message.ui-message-warn {\n  background: var(--curinos-color-semantic-warning-2);\n  border-color: var(--curinos-color-semantic-warning-1);\n  color: var(--curinos-color-semantic-warning-3);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-message-error,\nbody:not(.primeng-default) .ui-messages.ui-messages-error,\nbody:not(.primeng-default) .ui-message.ui-message-error {\n  background: var(--curinos-color-semantic-danger-2);\n  border-color: var(--curinos-color-semantic-danger-1);\n  color: var(--curinos-color-semantic-danger-3);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-message-content {\n  padding: $control-padding-x;\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-summary {\n  font-weight: var(--curinos-typography-font-weight-medium);\n}\n\nbody:not(.primeng-default) .ui-toast .ui-toast-detail {\n  font-weight: var(--curinos-typography-font-weight-regular);\n}\n\n// Tooltip inverts, matching the primary button pairing.\nbody:not(.primeng-default) .ui-tooltip .ui-tooltip-text {\n  padding: 6px 8px;\n  border-radius: var(--curinos-dimensions-radii-semantic-buttons);\n  background: var(--curinos-color-foreground-1);\n  box-shadow: none;\n  font-family: var(--curinos-typography-families-body);\n  font-size: var(--curinos-typography-font-size-xs);\n  font-weight: var(--curinos-typography-font-weight-medium);\n  color: var(--curinos-color-background-1);\n}\n\nbody:not(.primeng-default) .ui-tooltip.ui-tooltip-right .ui-tooltip-arrow {\n  border-right-color: var(--curinos-color-foreground-1);\n}\n\nbody:not(.primeng-default) .ui-tooltip.ui-tooltip-left .ui-tooltip-arrow {\n  border-left-color: var(--curinos-color-foreground-1);\n}\n\nbody:not(.primeng-default) .ui-tooltip.ui-tooltip-top .ui-tooltip-arrow {\n  border-top-color: var(--curinos-color-foreground-1);\n}\n\nbody:not(.primeng-default) .ui-tooltip.ui-tooltip-bottom .ui-tooltip-arrow {\n  border-bottom-color: var(--curinos-color-foreground-1);\n}"
        },
